class SettingsPage extends StatefulWidget {const SettingsPage({super.key});@override State<SettingsPage>createState()=>_SettingsPageState();}
class _SettingsPageState extends State<SettingsPage>{final _accounts=AccountRepository(AppDatabase.instance);final _hpp=HppRepository(AppDatabase.instance);Account? _account;List<HppMaster> _items=[];bool _loading=true;Future<void>_load()async{final a=await _accounts.activeAccount();final h=a==null?<HppMaster>[]:await _hpp.list(a.id!,activeOnly:false);if(mounted)setState((){_account=a;_items=h;_loading=false;});} @override void initState(){super.initState();_load();}Future<void>_add([HppMaster? x])async{final n=TextEditingController(text:x?.name),p=TextEditingController(text:x?.unitAmount.toString());final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(x==null?'Create HPP':'Edit HPP'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Nama HPP')),TextField(controller:p,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Harga HPP'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('CANCEL')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('SAVE'))]));final amount=Rupiah.parse(p.text);if(ok==true&&_account!=null&&n.text.trim().isNotEmpty&&amount!=null){if(x==null) {
